def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(i, j, path):
        if len(path) == k:
            return path

        min_path = []
        for dx, dy in directions:
            x, y = i + dx, j + dy
            if 0 <= x < n and 0 <= y < n:
                result = dfs(x, y, path + [grid[x][y]])
                if result and (not min_path or len(result) < len(min_path)):
                    min_path = result

        return min_path

    min_val = []
    for i in range(n):
        for j in range(n):
            result = dfs(i, j, [grid[i][j]])
            if result and (not min_val or len(result) < len(min_val)):
                min_val = result

    return min_val

